const env = typeof $env === 'object' ? $env : {};

function required(name) {
  const value = String(env[name] || '').trim();
  if (!value) {
    throw new Error('Missing required environment variable: ' + name);
  }
  return value;
}

const githubRepo = required('GITHUB_REPO');
const [owner, repoName] = githubRepo.split('/');
if (!owner || !repoName) {
  throw new Error('GITHUB_REPO must use owner/repo format, for example n8n-io/n8n');
}

const language = String(env.SUMMARY_LANGUAGE || 'EN').trim().toUpperCase();
if (!['EN', 'FR'].includes(language)) {
  throw new Error('SUMMARY_LANGUAGE must be EN or FR');
}

const lookbackDays = Math.max(1, Math.min(31, Number(env.LOOKBACK_DAYS || 7)));
const until = new Date();
const since = new Date(until.getTime() - lookbackDays * 24 * 60 * 60 * 1000);

const githubApiBaseUrl = String(env.GITHUB_API_BASE_URL || 'https://api.github.com').replace(/\/+$/, '');
const anthropicApiBaseUrl = String(env.ANTHROPIC_API_BASE_URL || 'https://api.anthropic.com').replace(/\/+$/, '');

return [{
  json: {
    githubRepo,
    owner,
    repoName,
    language,
    lookbackDays,
    sinceIso: since.toISOString(),
    untilIso: until.toISOString(),
    sinceDate: since.toISOString().slice(0, 10),
    untilDate: until.toISOString().slice(0, 10),
    githubToken: required('GITHUB_TOKEN'),
    anthropicApiKey: required('ANTHROPIC_API_KEY'),
    discordWebhookUrl: required('DISCORD_WEBHOOK_URL'),
    githubApiBaseUrl,
    anthropicMessagesUrl: anthropicApiBaseUrl + '/v1/messages'
  }
}];

const config = $json;

const headers = {
  Accept: 'application/vnd.github+json',
  Authorization: 'Bearer ' + config.githubToken,
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'n8n-claude-weekly-board-report'
};

async function githubJson(path) {
  const data = await helpers.httpRequest({
    method: 'GET',
    url: config.githubApiBaseUrl + path,
    headers,
    json: true
  });
  return data;
}

async function githubPages(path, limitPages = 3) {
  const out = [];
  for (let page = 1; page <= limitPages; page += 1) {
    const pagePath = path + (path.includes('?') ? '&' : '?') + 'per_page=100&page=' + page;
    const data = await githubJson(pagePath);
    const rows = Array.isArray(data) ? data : data?.items || [];
    out.push(...rows);
    if (rows.length < 100) break;
  }
  return out;
}

const repoPath = config.owner + '/' + config.repoName;
const commitsRaw = await githubPages('/repos/' + repoPath + '/commits?since=' + encodeURIComponent(config.sinceIso) + '&until=' + encodeURIComponent(config.untilIso));
const closedIssuesRaw = await githubPages('/search/issues?q=' + encodeURIComponent('repo:' + repoPath + ' is:issue is:closed closed:' + config.sinceDate + '..' + config.untilDate));
const mergedPrsRaw = await githubPages('/search/issues?q=' + encodeURIComponent('repo:' + repoPath + ' is:pr is:merged merged:' + config.sinceDate + '..' + config.untilDate));

const commits = commitsRaw.map((commit) => ({
  sha: String(commit.sha || '').slice(0, 7),
  author: commit.author?.login || commit.commit?.author?.name || 'unknown',
  message: String(commit.commit?.message || '').split('\n')[0].slice(0, 180),
  date: commit.commit?.author?.date,
  url: commit.html_url
}));

const closedIssues = closedIssuesRaw
  .filter((issue) => !issue.pull_request)
  .map((issue) => ({
    number: issue.number,
    title: issue.title,
    labels: (issue.labels || []).map((label) => label.name),
    closedAt: issue.closed_at,
    author: issue.user?.login || 'unknown',
    url: issue.html_url
  }));

const mergedPrs = mergedPrsRaw.map((pr) => ({
  number: pr.number,
  title: pr.title,
  mergedAt: pr.closed_at,
  author: pr.user?.login || 'unknown',
  url: pr.html_url
}));

const contributorMap = new Map();
for (const commit of commits) {
  contributorMap.set(commit.author, (contributorMap.get(commit.author) || 0) + 1);
}
for (const pr of mergedPrs) {
  contributorMap.set(pr.author, (contributorMap.get(pr.author) || 0) + 1);
}

const topContributors = [...contributorMap.entries()]
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([name, activityCount]) => ({ name, activityCount }));

const labelCounts = {};
for (const issue of closedIssues) {
  for (const label of issue.labels || []) {
    labelCounts[label] = (labelCounts[label] || 0) + 1;
  }
}

const riskKeywords = /\b(revert|rollback|hotfix|incident|security|broken|failure|regression|urgent)\b/i;
const riskSignals = [
  ...commits.filter((commit) => riskKeywords.test(commit.message)).map((commit) => ({
    type: 'commit',
    ref: commit.sha,
    title: commit.message,
    url: commit.url
  })),
  ...mergedPrs.filter((pr) => riskKeywords.test(pr.title)).map((pr) => ({
    type: 'pr',
    ref: '#' + pr.number,
    title: pr.title,
    url: pr.url
  })),
  ...closedIssues.filter((issue) => riskKeywords.test(issue.title) || (issue.labels || []).some((label) => riskKeywords.test(label))).map((issue) => ({
    type: 'issue',
    ref: '#' + issue.number,
    title: issue.title,
    url: issue.url
  }))
].slice(0, 12);

return [{
  json: {
    ...config,
    stats: {
      commits: commits.length,
      closedIssues: closedIssues.length,
      mergedPrs: mergedPrs.length,
      contributors: topContributors.length,
      riskSignals: riskSignals.length
    },
    labelCounts,
    topContributors,
    riskSignals,
    commits: commits.slice(0, 80),
    closedIssues: closedIssues.slice(0, 60),
    mergedPrs: mergedPrs.slice(0, 60)
  }
}];

const data = $json;
const languageName = data.language === 'FR' ? 'French' : 'English';
const rawActivity = JSON.stringify({
  stats: data.stats,
  labelCounts: data.labelCounts,
  topContributors: data.topContributors,
  riskSignals: data.riskSignals,
  commits: data.commits,
  closedIssues: data.closedIssues,
  mergedPrs: data.mergedPrs
}, null, 2);

const prompt = [
  'You are a senior engineering program manager writing a weekly board-style development report.',
  '',
  'Repository: ' + data.githubRepo,
  'Window: ' + data.sinceIso + ' to ' + data.untilIso,
  'Output language: ' + languageName,
  '',
  'Write a narrative summary from the evidence only. Do not invent roadmap items, names, metrics, or impact.',
  '',
  'Return Markdown with exactly these sections:',
  '1. Executive Pulse - 3 short bullets for leadership.',
  '2. Narrative Summary - one cohesive paragraph.',
  '3. What Shipped - merged PR highlights with PR numbers where available.',
  '4. Issues Closed - resolved user/developer problems with issue numbers where available.',
  '5. Contributor Spotlight - recognize contributors without ranking them aggressively.',
  '6. Risk Radar - mention only observed risks or say "No obvious risk signals in the sampled activity."',
  '7. Audit Trail - compact counts and date range.',
  '',
  'Raw activity JSON:',
  rawActivity
].join('\n');

return [{
  json: {
    ...data,
    claudeRequest: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 1800,
      messages: [
        {
          role: 'user',
          content: prompt
        }
      ]
    }
  }
}];

const source = $('Build Claude Board Brief').first().json;
const response = $json;
const summary = Array.isArray(response.content)
  ? response.content.map((part) => part.text || '').filter(Boolean).join('\n\n').trim()
  : String(response.summary || '').trim();

if (!summary) {
  throw new Error('Claude response did not include text content');
}

const audit = {
  repo: source.githubRepo,
  since: source.sinceIso,
  until: source.untilIso,
  language: source.language,
  model: source.claudeRequest.model,
  stats: source.stats
};

const title = 'Weekly board report: ' + source.githubRepo;
const intro = source.stats.commits + ' commits, ' + source.stats.mergedPrs + ' merged PRs, ' + source.stats.closedIssues + ' closed issues';
const body = summary.length > 3500 ? summary.slice(0, 3490) + '\n...' : summary;

return [{
  json: {
    discordWebhookUrl: source.discordWebhookUrl,
    summary,
    audit,
    discordPayload: {
      content: title + '\n' + intro,
      embeds: [
        {
          title,
          description: body,
          color: 3447003,
          fields: [
            { name: 'Repository', value: source.githubRepo, inline: true },
            { name: 'Language', value: source.language, inline: true },
            { name: 'Window', value: source.sinceDate + ' to ' + source.untilDate, inline: false },
            { name: 'Audit JSON', value: 'Included in n8n execution data for traceability.', inline: false }
          ],
          footer: {
            text: 'Generated by n8n + Claude Sonnet 4'
          }
        }
      ]
    }
  }
}];
